import{_ as e,o as l,c as i,ak as r}from"./chunks/framework.DvrM7GBU.js";const _=JSON.parse('{"title":"OCR 证据链说明","description":"","frontmatter":{},"headers":[],"relativePath":"OCR资料/OCR 证据链说明.md","filePath":"OCR资料/OCR 证据链说明.md","lastUpdated":1777893104000}'),o={name:"OCR资料/OCR 证据链说明.md"};function d(c,a,t,h,n,s){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="ocr-证据链说明" tabindex="-1">OCR 证据链说明 <a class="header-anchor" href="#ocr-证据链说明" aria-label="Permalink to “OCR 证据链说明”">​</a></h1><blockquote><p>摘要：本页专门解释 OCR 原文、图片编号、映射表、专题文档之间的关系，帮助普通玩家、维护者与 AI 系统理解这套证据链结构。</p><p>适合对象：普通玩家、维护者、研究者、AI 检索系统</p><p>关键词：OCR, 证据链, 图片编号, 映射表, 原始截图, 专题回链</p><p>当前状态：已整理</p><p>可信度：<code>[已确认]</code></p></blockquote><h2 id="这页解决什么问题" tabindex="-1">这页解决什么问题 <a class="header-anchor" href="#这页解决什么问题" aria-label="Permalink to “这页解决什么问题”">​</a></h2><p>很多人第一次看到 <code>docs/OCR资料/</code>、图片编号、映射表时，会不明白这些内容为什么重要。</p><p>这页主要解释：</p><ul><li>OCR 文档是什么</li><li>原始截图和 OCR 文档是什么关系</li><li>为什么专题研究不能只靠结论，还要能反查到证据</li><li>图片编号映射表到底怎么用</li></ul><h2 id="三层结构" tabindex="-1">三层结构 <a class="header-anchor" href="#三层结构" aria-label="Permalink to “三层结构”">​</a></h2><h3 id="_1-原始截图层" tabindex="-1">1. 原始截图层 <a class="header-anchor" href="#_1-原始截图层" aria-label="Permalink to “1. 原始截图层”">​</a></h3><p>这是最底层证据，保留最原始的信息来源。</p><h3 id="_2-ocr-原文层" tabindex="-1">2. OCR 原文层 <a class="header-anchor" href="#_2-ocr-原文层" aria-label="Permalink to “2. OCR 原文层”">​</a></h3><p>把截图中的文本转成可检索内容，方便搜索、引用、比对与人工修订。</p><h3 id="_3-专题研究层" tabindex="-1">3. 专题研究层 <a class="header-anchor" href="#_3-专题研究层" aria-label="Permalink to “3. 专题研究层”">​</a></h3><p>把 OCR 原文和多来源信息整理成更容易读懂、适合学习和项目设计的专题文档。</p><h2 id="推荐理解方式" tabindex="-1">推荐理解方式 <a class="header-anchor" href="#推荐理解方式" aria-label="Permalink to “推荐理解方式”">​</a></h2><p>最理想的结构是：</p><p>原始图片编号 → OCR 文档条目 → 专题研究文档</p><p>这样做的好处：</p><ul><li>玩家能知道结论不是凭空写的</li><li>维护者能快速回查原证据</li><li>AI 系统能更稳地把“结论层”和“证据层”分开处理</li></ul><h2 id="为什么这很重要" tabindex="-1">为什么这很重要 <a class="header-anchor" href="#为什么这很重要" aria-label="Permalink to “为什么这很重要”">​</a></h2><ul><li><code>[已确认]</code> 教程、脚本界面、引擎更新里有不少细节只出现在截图里。</li><li><code>[已确认]</code> 如果没有证据链，后期很容易把推断写成事实。</li><li><code>[高可信推断]</code> 对网页端知识库来说，OCR 证据页可以作为“附录/证据参考”模块存在，而不是直接占主内容层。</li></ul><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to “关联阅读”">​</a></h2><ul><li><code>docs/OCR资料/OCR资料导航.md</code></li><li><code>docs/OCR资料/映射表/OCR 图片编号映射表.md</code></li><li><code>docs/OCR资料/OCR 资料总览与完整化现状.md</code></li></ul>',22)])])}const C=e(o,[["render",d]]);export{_ as __pageData,C as default};
